#include <string>
#include <regex>

std::string markdownToHtml(const std::string& markdown) {
    // Define a regex pattern to match markdown syntax
    std::regex pattern(R"(
        (\#\s*(\d+)\s*(.*?))
    )");

    // Create a match object to store the matched text
    std::smatch match;

    // Use the regex pattern to match the markdown text
    while (std::regex_search(markdown, match, pattern)) {
        // Replace the matched text with HTML syntax
        std::string html = "<h" + match[1].str() + ">" + match[2].str() + "</h" + match[1].str() + ">";

        // Replace the matched text with the HTML syntax
        markdown.replace(match[0].str(), html);
    }

    // Return the HTML formatted text
    return markdown;
}
```

